"""Build bilingual professional pages. Publication records remain in cva.Rmd."""
from pathlib import Path
import subprocess,re,html,shutil,argparse
parser=argparse.ArgumentParser()
parser.add_argument("--pandoc",default=shutil.which("pandoc") or "/opt/homebrew/bin/pandoc")
args=parser.parse_args()
R=Path(__file__).resolve().parent
PANDOC=args.pandoc

def tr(es,en,lang):return es if lang=='es' else en

def button(text,url,kind='primary',download=False):return f'<a class="button {kind}" href="{url}"'+(' download' if download else '')+f'>{text}<span aria-hidden="true">↗</span></a>'

def download(l):
 p='' if l=='es' else '../'
 return f'''<aside class="download" id="transfer-infographic"><div><p class="eyebrow">{tr('El perfil de un vistazo','The profile at a glance',l)}</p><h3>{tr('Experiencia que puedes llevar contigo.','Expertise you can take with you.',l)}</h3><p>{tr('Ámbitos de aplicación, formación y liderazgo científico en una infografía descargable.','Applications, training and scientific leadership in a downloadable infographic.',l)}</p></div>{button(tr('Descargar PDF · 1,2 MB','Download PDF · Spanish · 1.2 MB',l),p+'downloads/xavier-barber-ia-ciencia-datos.pdf',download=True)}</aside>'''

def shell(l,key,title,desc,content):
 p='' if l=='es' else '../'
 names={'index':tr('Inicio','Home',l),'xbarber':tr('Colaboración','Collaboration',l),'training':tr('Formación','Training',l),'cva':tr('Investigación','Research',l),'about':tr('Perfil','Profile',l)}
 nav=''.join(f'<a href="{k}.html"'+(' aria-current="page"' if k==key else '')+f'>{v}</a>' for k,v in names.items())
 alternate=('en/' if l=='es' else '../')+key+'.html'
 canonical='https://xavierbarber.github.io/'+('' if l=='es' else 'en/')+('' if key=='index' else key+'.html')
 return f'''<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · Xavier Barber</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="es" href="https://xavierbarber.github.io/{key}.html"><link rel="alternate" hreflang="en" href="https://xavierbarber.github.io/en/{key}.html"><meta property="og:title" content="{html.escape(title)} · Xavier Barber"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://xavierbarber.github.io/photos/xavier-speaking.svg"><meta name="theme-color" content="#162c34"><link rel="stylesheet" href="{p}assets/site.css"><script defer src="{p}assets/site.js"></script></head><body><a class="skip" href="#main">{tr('Saltar al contenido','Skip to content',l)}</a><header class="site-header"><nav class="nav wrap" aria-label="{tr('Navegación principal','Main navigation',l)}"><a class="brand" href="index.html">Xavier Barber<span>.</span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">{tr('Menú','Menu',l)} ☰</button><div class="nav-links" id="navigation">{nav}<a class="nav-contact" href="#contact">{tr('Hablemos','Get in touch',l)}</a><a class="lang" href="{alternate}" lang="{tr('en','es',l)}" aria-label="{tr('Read this page in English','Leer esta página en español',l)}">{tr('EN','ES',l)} ↗</a></div></nav></header><main id="main">{content}</main><section id="contact" class="contact" aria-labelledby="contact-title"><div class="wrap contact-grid"><div><p class="eyebrow">{tr('Empecemos por tu pregunta','Start with your question',l)}</p><h2 id="contact-title">{tr('¿Qué reto quieres resolver?','What challenge are you working on?',l)}</h2><p>{tr('Cuéntame qué necesitas decidir, con qué datos cuentas y a quién debe ayudar la solución.','Tell me what you need to decide, what data you have and who the solution should help.',l)}</p></div><div><a class="email" href="mailto:xbarber@umh.es">xbarber@umh.es ↗</a><small>Universidad Miguel Hernández de Elche · i-MInD<br>{tr('Investigación · Colaboración · Formación','Research · Collaboration · Training',l)}</small></div></div></section><footer class="footer"><div class="wrap footer-row"><p>© 2026 Xavier Barber · {tr('Dénia / Elche, España','Dénia / Elche, Spain',l)}</p><div class="footer-links"><a href="https://orcid.org/0000-0003-3079-5855">ORCID</a><a href="https://scholar.google.com/citations?user=KUzOpI4AAAAJ&amp;hl=en">Google Scholar</a><a href="https://portalinvestigacion.umh.es/investigadores/2181582/detalle">{tr('Perfil UMH','UMH profile',l)} ↗</a></div></div></footer></body></html>'''

def pagehead(l,eyebrow,title,intro):return f'<div class="page-head"><div class="wrap"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="intro">{intro}</p></div></div>'

def home(l):
 p='' if l=='es' else '../'
 head=tr('Ciencia rigurosa.<br><em>Decisiones con sentido.</em>','Rigorous science.<br><em>Meaningful decisions.</em>',l)
 s=f'''<section class="hero"><div class="wrap hero-inner"><div><p class="eyebrow">{tr('Inteligencia artificial y ciencia de datos','Artificial intelligence & data science',l)}</p><h1>{head}</h1><p class="intro">{tr('Conecto investigación, datos y conocimiento del problema para desarrollar soluciones útiles para empresas, administraciones y equipos de investigación.','I connect research, data and domain knowledge to develop useful solutions for companies, public institutions and research teams.',l)}</p><div class="actions">{button(tr('Exploremos tu proyecto','Let’s explore your project',l),'xbarber.html')}{button(tr('Conoce mi investigación','Explore my research',l),'cva.html','light')}</div></div><figure class="hero-figure"><img src="{p}photos/xavier-speaking.svg" width="1400" height="933" fetchpriority="high" alt="{tr('Xavier Barber interviniendo en un acto cultural','Xavier Barber speaking at a cultural event',l)}"><figcaption><strong>Xavier Barber</strong><small>{tr('Catedrático de Estadística e Investigación Operativa · UMH','Full Professor of Statistics and Operations Research · UMH',l)}</small></figcaption></figure></div></section>'''
 s+=f'''<div class="credentials"><div class="wrap credential-inner"><div><strong>i-MInD · UMH</strong>{tr('Matemáticas, IA y ciencia de datos','Mathematics, AI & data science',l)}</div><div><strong>International Biometric Society</strong>Chair, Representative Council · 2026–2027</div><div><strong>{tr('Ética e integridad científica','Research ethics & integrity',l)}</strong>{tr('Miembro de los comités CEII y CEEA · UMH','Member of CEII & CEEA committees · UMH',l)}</div></div></div>'''
 services=[('01',tr('Desarrollar una solución','Develop a solution',l),tr('Diseño de estudios, modelos predictivos y herramientas para apoyar decisiones concretas.','Study design, predictive models and tools to support specific decisions.',l),'xbarber.html'),('02',tr('Investigar con rigor','Investigate rigorously',l),tr('Aprendizaje automático, modelos bayesianos y análisis de eficiencia conectados con aplicaciones reales.','Machine learning, Bayesian modelling and efficiency analysis connected to real applications.',l),'cva.html'),('03',tr('Capacitar a un equipo','Build your team’s skills',l),tr('Formación especializada en IA, ciencia de datos y metodología para profesionales.','Specialised training in AI, data science and research methods for professionals.',l),'training.html')]
 s+=f'<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">{tr("Cómo podemos colaborar","How we can work together",l)}</p><h2>{tr("Del problema a una respuesta útil.","From a problem to a useful answer.",l)}</h2></div><p>{tr("Cada proyecto empieza entendiendo qué hace falta resolver. A partir de ahí, elijo los métodos, contrasto los resultados y trabajo con el equipo que los utilizará.","Every project starts by understanding what needs to be solved. From there, I choose the methods, evaluate the results and work with the team that will use them.",l)}</p></div><div class="service-list">'
 for num,title,body,url in services:s+=f'<a class="service" href="{url}"><span class="number">{num}</span><h3>{title}</h3><p>{body}</p><span class="arrow" aria-hidden="true">↗</span></a>'
 s+='</div></div></section>'
 s+=f'''<section class="section soft"><div class="wrap"><div class="section-head"><div><p class="eyebrow">{tr('Experiencia aplicada','Applied expertise',l)}</p><h2>{tr('Datos al servicio de las personas y su entorno.','Data that serves people and their environment.',l)}</h2></div><p>{tr('Una selección de trabajos que conecta el desarrollo de métodos con necesidades sociales, sanitarias y ambientales.','Selected work connecting methodological development with social, health and environmental needs.',l)}</p></div><div class="cases"><article class="case featured"><p class="eyebrow">{tr('IA centrada en las personas','Human-centred AI',l)} · VioGén-2</p><h3>{tr('Apoyar la protección frente a la violencia.','Supporting protection against violence.',l)}</h3><div class="case-graphic" aria-hidden="true">{''.join(f'<span style="height:{n}px"></span>' for n in [22,40,30,67,52,88,65,105,78,115,92,62,44])}</div><p>{tr('Desarrollo y validación de modelos predictivos para la valoración del riesgo de reincidencia, dentro del proyecto ALTEA. Interpretabilidad, trazabilidad y control humano como objetivos de diseño.','Development and validation of predictive models for assessing repeat-offence risk within the ALTEA project. Interpretability, traceability and human oversight as design objectives.',l)}</p><a href="xbarber.html#human-centred">{tr('Conocer el ámbito de trabajo','Explore this work',l)} ↗</a></article><article class="case"><p class="eyebrow">{tr('Salud y bienestar','Health & wellbeing',l)}</p><h3>{tr('Herramientas para quienes cuidan.','Tools for the people who care.',l)}</h3><p>{tr('Entre otros ejemplos: predicción del riesgo musculoesquelético en cirujanos y análisis de la aceptación de la teleconsulta.','Examples include musculoskeletal risk prediction for surgeons and analysis of remote-consultation acceptance.',l)}</p><a href="xbarber.html#health">{tr('Ver aplicaciones en salud','See health applications',l)} ↗</a></article><article class="case"><p class="eyebrow">{tr('Medio ambiente y recursos','Environment & resources',l)}</p><h3>{tr('Comprender el riesgo. Orientar la adaptación.','Understand risk. Inform adaptation.',l)}</h3><p>{tr('Modelización del riesgo térmico en acuicultura, distribución de especies y uso de datos ambientales para apoyar la gestión.','Modelling thermal risk in aquaculture, species distributions and environmental data to support management.',l)}</p><a href="xbarber.html#environment">{tr('Explorar las aplicaciones','Explore applications',l)} ↗</a></article></div></div></section>'''
 s+=f'''<section class="section"><div class="wrap photo-panel"><img src="{p}photos/spatial-statistics-talk.svg" width="1200" height="900" loading="lazy" alt="{tr('Presentación científica sobre modelos espaciales y temporales','Scientific presentation on spatial and temporal models',l)}"><div><p class="eyebrow">{tr('Investigación que sostiene la práctica','Research behind the practice',l)}</p><h2>{tr('La solidez de un método importa.','The strength of a method matters.',l)}</h2><p>{tr('Mi trabajo combina aprendizaje automático, modelos bayesianos y análisis de eficiencia. La pregunta no termina en la predicción: también importa entender la incertidumbre y cuándo una herramienta resulta útil.','My work combines machine learning, Bayesian models and efficiency analysis. Prediction is only part of the question: understanding uncertainty and when a tool is useful matters too.',l)}</p><a class="text-link" href="cva.html">{tr('Líneas de investigación y publicaciones','Research areas and publications',l)} ↗</a></div></div></section>'''
 s+=f'''<section class="section soft"><div class="wrap"><div class="section-head"><div><p class="eyebrow">{tr('Perfil y compromiso','Profile & commitment',l)}</p><h2>{tr('Una trayectoria abierta a la colaboración.','A career built around collaboration.',l)}</h2></div><p>{tr('Catedrático en la Universidad Miguel Hernández de Elche. Investigación interdisciplinar, formación y participación en la comunidad científica internacional.','Full Professor at Universidad Miguel Hernández de Elche. Interdisciplinary research, training and participation in the international scientific community.',l)}</p></div><div class="leadership"><div><p class="eyebrow">01 · {tr('Comunidad científica','Scientific community',l)}</p><h3>International Biometric Society</h3><p>{tr('Presidente del Representative Council y miembro ex officio del Executive Board, 2026–2027.','Chair of the Representative Council and ex officio member of the Executive Board, 2026–2027.',l)}</p></div><div><p class="eyebrow">02 · {tr('Investigación responsable','Responsible research',l)}</p><h3>{tr('Ética e integridad','Ethics & integrity',l)}</h3><p>{tr('Miembro con perfil bioestadístico de los comités de Ética e Integridad en la Investigación y de Ética de Experimentación Animal de la UMH.','Biostatistical member of the UMH Research Ethics and Integrity Committee and Animal Experimentation Ethics Committee.',l)}</p></div><div><p class="eyebrow">03 · {tr('Compartir conocimiento','Sharing knowledge',l)}</p><h3>{tr('Docencia y formación','Teaching & training',l)}</h3><p>{tr('Formación universitaria y especializada, supervisión de investigación y capacitación de profesionales en IA y ciencia de datos.','University and specialised teaching, research supervision and professional training in AI and data science.',l)}</p></div></div><a class="text-link" href="about.html">{tr('Conocer mi trayectoria','Read my profile',l)} ↗</a>{download(l)}</div></section>'''
 return s

sector_data=[('human-centred','IA centrada en las personas','Human-centred AI','Valoración del riesgo de reincidencia en VioGén-2 y análisis de encuestas ciudadanas a gran escala para comprender necesidades y apoyar decisiones públicas.','Repeat-offence risk assessment in VioGén-2 and large-scale citizen survey analysis to understand needs and support public decisions.','https://comunicacion.umh.es/2026/04/20/investigadores-de-la-umh-participan-en-el-desarrollo-del-nuevo-sistema-viogen-2-para-la-mejora-de-la-valoracion-del-riesgo-en-violencia-de-genero/'),('health','Salud y prevención','Health & prevention','Diseño y análisis de estudios clínicos, evaluación de tratamientos y modelos predictivos. Casos destacados incluyen una calculadora de riesgo musculoesquelético en cirujanos y una herramienta de aceptación de teleconsulta.','Clinical study design and analysis, treatment evaluation and predictive models. Selected examples include a musculoskeletal risk calculator for surgeons and a remote-consultation acceptance tool.','https://doi.org/10.1007/s00464-024-11237-4'),('environment','Acuicultura y medio marino','Aquaculture & marine environments','Riesgo térmico, distribución de especies e integración de datos ambientales. Mapas y modelos para evaluar exposición, emplazamientos y opciones de adaptación.','Thermal risk, species distributions and environmental data integration. Maps and models to assess exposure, locations and adaptation options.','https://doi.org/10.1016/j.aquaculture.2024.740917'),('efficiency','Eficiencia y productividad','Efficiency & productivity','Aprendizaje automático, fronteras de producción y software abierto eat. Comparación de unidades con distintos recursos y resultados para identificar oportunidades de mejora.','Machine learning, production frontiers and the open-source eat software. Comparing units with different resources and outputs to identify improvement opportunities.','https://doi.org/10.32614/RJ-2022-054'),('circular','Agricultura y economía circular','Agriculture & circular economy','Compost Calculator, caracterización de lodos, valorización de residuos, riego y zonificación de suelos. Evaluación de procesos y alternativas de aprovechamiento de recursos.','Compost Calculator, sludge characterisation, waste valorisation, irrigation and soil zoning. Evaluating processes and alternatives for resource use.','https://doi.org/10.1016/j.talanta.2013.02.009'),('golf','Golf y gestión del territorio','Golf & land management','Gestión del césped, fertilización, valorización de residuos y seguimiento con drones. Análisis para orientar el mantenimiento y el uso de recursos.','Turf management, fertilisation, waste valorisation and drone-based monitoring. Analysis to inform maintenance and resource use.','https://doi.org/10.3390/agronomy11091870'),('food','Industria alimentaria','Food industry','Diseño experimental, formulación, conservación, ingredientes de coproductos y preferencias del consumidor. Comparación de productos, procesos y aceptación.','Experimental design, formulation, preservation, coproduct ingredients and consumer preferences. Comparing products, processes and acceptance.','https://doi.org/10.1111/1750-3841.13501')]

def collaboration(l):
 s=pagehead(l,tr('Colaboración y transferencia','Collaboration & knowledge transfer',l),tr('Tu reto, una pregunta bien planteada y un método sólido.','Your challenge, a clear question and a sound method.',l),tr('Trabajo con empresas, administraciones y equipos de investigación para convertir datos en evidencia, modelos y herramientas de apoyo.','I work with companies, public institutions and research teams to turn data into evidence, models and decision-support tools.',l))
 s+='<div class="wrap page-body"><div class="section-head"><h2>'+tr('Experiencia en contextos diferentes.','Experience across different contexts.',l)+'</h2><p>'+tr('Cada aplicación exige comprender el sector y validar los resultados en su contexto. Estos ámbitos ilustran la experiencia disponible para plantear nuevas colaboraciones.','Every application requires domain knowledge and validation in context. These areas illustrate the experience available for new collaborations.',l)+'</p></div><div class="sector-grid">'
 for id,es,en,pes,pen,url in sector_data:s+=f'<article class="sector" id="{id}"><h3>{tr(es,en,l)}</h3><p>{tr(pes,pen,l)}</p><a class="text-link" href="{url}">{tr("Referencia del trabajo","Related work",l)} ↗</a></article>'
 s+='</div>'+download(l)
 s+=f'<div class="prose"><h2>{tr("Cómo se plantea una colaboración","How a collaboration takes shape",l)}</h2><ol class="step-list">'
 for es,en in [('Delimitar la decisión, los objetivos y las personas que utilizarán el resultado.','Define the decision, objectives and people who will use the results.'),('Revisar los datos y diseñar el estudio o el plan de análisis.','Review the data and design the study or analysis plan.'),('Desarrollar y validar los métodos, explicando sus resultados y límites.','Develop and validate methods, explaining their results and limitations.'),('Entregar un informe, una herramienta o formación que permita utilizar el trabajo.','Deliver a report, tool or training that makes the work usable.')]:s+=f'<li><span>{tr(es,en,l)}</span></li>'
 s+=f'</ol><h2>{tr("Un punto de partida concreto","A concrete starting point",l)}</h2><p>{tr("En el primer contacto, resulta útil explicar el problema, el tipo de datos disponibles y el resultado que necesitas. Con esa información podemos valorar el alcance y la forma de colaboración.","For an initial conversation, it helps to describe the problem, the data available and the outcome you need. We can then consider the scope and the most suitable form of collaboration.",l)}</p></div></div>'
 return s

def training(l):
 p='' if l=='es' else '../'
 s=pagehead(l,tr('Formación especializada','Specialised training',l),tr('Conocimiento que un equipo puede poner en práctica.','Knowledge a team can put to work.',l),tr('Experiencia docente en inteligencia artificial, ciencia de datos y metodología, aplicada a las necesidades de profesionales y organizaciones.','Teaching experience in artificial intelligence, data science and methodology, connected to the needs of professionals and organisations.',l))
 data=[('IA para administraciones','AI for public institutions','Herramientas de IA generativa, análisis de documentos, formulación de instrucciones y uso responsable en tareas administrativas.','Generative AI tools, document analysis, prompting and responsible use in administrative work.'),('Ciencia de datos y aprendizaje automático','Data science & machine learning','Comprender los datos, seleccionar métodos y evaluar los resultados de modelos predictivos.','Understanding data, selecting methods and evaluating predictive models.'),('Diseño experimental y metodología','Experimental design & methodology','Planificación de estudios y formación metodológica para equipos de investigación, incluida la experimentación animal.','Study planning and methodological training for research teams, including animal experimentation.'),('Salud e innovación docente','Health & teaching innovation','Participación en formación especializada en salud e innovación docente aplicada. Contenidos ajustados al papel y las necesidades de cada profesional.','Participation in specialised health training and applied teaching innovation. Content aligned with professional roles and needs.')]
 s+='<div class="wrap page-body"><div class="sector-grid">'
 for a,b,c,d in data:s+=f'<article class="sector"><h3>{tr(a,b,l)}</h3><p>{tr(c,d,l)}</p></article>'
 s+=f'''</div><div class="photo-panel section"><img src="{p}photos/teaching-award.svg" width="506" height="900" loading="lazy" style="object-fit:contain;background:#e8ede8;height:380px" alt="{tr('Reconocimiento Talento Docente UMH 2024','UMH Teaching Talent Award 2024',l)}"><div><p class="eyebrow">{tr('Experiencia docente','Teaching experience',l)}</p><h2>{tr('Rigor, claridad y contexto.','Rigour, clarity and context.',l)}</h2><p>{tr('Docencia universitaria desde 2005 y formación de postgrado para profesionales. Reconocimientos Talento Docente y evaluaciones excelentes en el programa DOCENTIA-UMH.','University teaching since 2005 and postgraduate training for professionals. Teaching Talent recognition and excellent evaluations in the DOCENTIA-UMH programme.',l)}</p><a class="text-link" href="mailto:xbarber@umh.es">{tr('Hablemos de las necesidades de tu equipo','Let’s discuss your team’s needs',l)} ↗</a></div></div><div class="prose"><h2>{tr('De la necesidad al programa','From a need to a programme',l)}</h2><p>{tr('El punto de partida es el nivel del equipo, sus tareas y los objetivos de aprendizaje. A partir de ahí se puede definir un programa con ejemplos relevantes, ejercicios y materiales de apoyo.','The starting point is the team’s experience, everyday tasks and learning goals. From there, a programme can be defined around relevant examples, exercises and supporting materials.',l)}</p></div></div>'''
 return s

def about(l):
 p='' if l=='es' else '../'
 s=pagehead(l,tr('Perfil profesional','Professional profile',l),tr('Investigar, colaborar y compartir conocimiento.','Research, collaboration and shared knowledge.',l),tr('Xavier Barber · Catedrático de Estadística e Investigación Operativa en la Universidad Miguel Hernández de Elche.','Xavier Barber · Full Professor of Statistics and Operations Research at Universidad Miguel Hernández de Elche.',l))
 s+=f'<div class="wrap page-body split"><aside class="side-nav"><a href="#career">{tr("Trayectoria","Career",l)}</a><a href="#leadership">{tr("Liderazgo científico","Scientific leadership",l)}</a><a href="#ethics">{tr("Ética e integridad","Ethics & integrity",l)}</a><a href="#personal">{tr("Más allá del trabajo","Beyond work",l)}</a></aside><div class="prose"><h2 id="career">{tr("Una base metodológica, muchas aplicaciones","A methodological foundation, many applications",l)}</h2><p>{tr("Mi actividad en i-MInD combina modelos bayesianos, aprendizaje automático y análisis de eficiencia. Colaboro con especialistas de salud, ecología, medio ambiente, industria y economía para abordar preguntas que necesitan tanto conocimiento del ámbito como rigor analítico.","My work at i-MInD combines Bayesian modelling, machine learning and efficiency analysis. I collaborate with specialists in health, ecology, environmental science, industry and economics on questions that need both domain knowledge and analytical rigour.",l)}</p><p>{tr("Doctor por la UMH desde 2009, con una investigación en modelos geoestadísticos para índices bioclimáticos dirigida por Javier Morales y Antonio López-Quílez. Diplomado en Estadística por la Universidad de Alicante y licenciado en Ciencias y Técnicas Estadísticas por la UMH.","I completed my PhD at UMH in 2009, researching geostatistical models for bioclimatic indices under Javier Morales and Antonio López-Quílez. I hold statistics degrees from Universidad de Alicante and UMH.",l)}</p><h2 id="leadership">{tr("Liderazgo y comunidad científica","Leadership & scientific community",l)}</h2><ul>'
 for es,en in [('Subdirector de i-MInD, Universidad Miguel Hernández de Elche.','Deputy Director of i-MInD, Universidad Miguel Hernández de Elche.'),('Chair del Representative Council de la International Biometric Society y miembro ex officio de su Executive Board, 2026–2027.','Chair of the International Biometric Society Representative Council and ex officio member of its Executive Board, 2026–2027.'),('Miembro de la Junta Ejecutiva de la Sociedad Española de Bioestadística.','Member of the Executive Committee of the Spanish Society of Biostatistics.'),('Responsable de la Unidad Mixta de Investigación UMH–FISABIO en Métodos Estadísticos en Ciencias de la Salud.','Head of the UMH–FISABIO Joint Research Unit on Statistical Methods in Health Sciences.'),('Vicerrector adjunto de Investigación en la UMH, 2011–2023.','Deputy Vice-Rector for Research at UMH, 2011–2023.'),('Actividad editorial y de revisión científica, incluida la edición estadística para Public Health Nutrition.','Editorial and peer-review activity, including statistical editing for Public Health Nutrition.')]:s+='<li>'+tr(es,en,l)+'</li>'
 s+=f'''</ul><p><a href="https://www.biometricsociety.org/about/governance">{tr('Gobernanza de la International Biometric Society','International Biometric Society governance',l)} ↗</a></p><h2 id="ethics">{tr('Ética e integridad en la investigación','Research ethics & integrity',l)}</h2><p>{tr('Desde septiembre de 2026, miembro con perfil bioestadístico de dos comités de la Universidad Miguel Hernández de Elche:','Since September 2026, biostatistical member of two committees at Universidad Miguel Hernández de Elche:',l)}</p><ul><li>{tr('Comité de Ética e Integridad en la Investigación (CEII).','Research Ethics and Integrity Committee (CEII).',l)}</li><li>{tr('Comité de Ética de Experimentación Animal (CEEA).','Animal Experimentation Ethics Committee (CEEA).',l)}</li></ul><h2 id="personal">{tr('Bicicleta, dolçaina y raíces','Cycling, dolçaina and roots',l)}</h2><p>{tr('Soy de Dénia. Hoy dedico mi tiempo de ocio a la bicicleta y a tocar la dolçaina: dos maneras de desconectar y compartir tiempo con otras personas. El remo también forma parte de mi trayectoria, aunque actualmente lo tengo en pausa.','I am from Dénia. These days, I spend my free time cycling and playing the dolçaina, a traditional Valencian wind instrument: two ways to switch off and spend time with others. Rowing is also part of my story, although I am currently taking a break from it.',l)}</p><div class="personal-gallery"><figure><img src="{p}photos/cycling.jpg" width="800" height="1200" loading="lazy" alt="{tr('Salida en bicicleta de montaña','Mountain biking',l)}"><figcaption>{tr('Bicicleta · tiempo al aire libre','Cycling · time outdoors',l)}</figcaption></figure><figure><img src="{p}photos/dolcaina.jpg" width="900" height="1200" loading="lazy" alt="{tr('Música compartida con la dolçaina','Sharing music with the dolçaina',l)}"><figcaption>{tr('Dolçaina · música y tradición','Dolçaina · music and tradition',l)}</figcaption></figure></div>{download(l)}</div></div>'''
 return s

def research(l):
 raw=subprocess.check_output([PANDOC,str(R/'cva.Rmd'),'--from=markdown','--to=html5','--wrap=none'],text=True)
 # Keep original bibliographic records and DOI links. Localise navigation and editorial prose only.
 if l=='es':
  protected=[]
  def keep_link(m):
   protected.append(m.group(0));return f'@@LINK{len(protected)-1}@@'
  raw=re.sub(r'<a\b[^>]*>.*?</a>',keep_link,raw,flags=re.S)
  changes={'CV and selected publications':'Investigación y publicaciones','Full Professor of Statistics and Operations Research':'Catedrático de Estadística e Investigación Operativa','Selected publications':'Publicaciones seleccionadas','Artificial Intelligence and Decision Making':'Inteligencia artificial y apoyo a decisiones','Spatial and Spatio-temporal Statistics':'Estadística espacial y espacio-temporal','Efficiency and Productivity Analysis':'Análisis de eficiencia y productividad','Selected Highly Cited and Interdisciplinary Work':'Trabajos destacados e interdisciplinares','Further Artificial Intelligence Publications':'Otras publicaciones en inteligencia artificial','Academic profile':'Trayectoria académica','Education':'Formación académica','Teaching and supervision':'Docencia y dirección de investigación','Research projects and knowledge transfer':'Proyectos y transferencia','Scientific leadership':'Liderazgo científico','Spatial statistics':'Estadística espacial','Efficiency &amp; productivity':'Eficiencia y productividad','Highly cited work':'Trabajos destacados','Artificial Intelligence papers':'Publicaciones en IA','Artificial Intelligence':'Inteligencia artificial','citations':'citas','Preprint · Dataset resource':'Preprint · Recurso de datos','Spatial &amp; environmental statistics':'Estadística espacial y ambiental'}
  for a,b in changes.items():raw=raw.replace(a,b)
  for i,link in enumerate(protected):raw=raw.replace(f'@@LINK{i}@@',link)
  raw=raw.replace('Alicante, Spain','Alicante, España')
  for a,b in changes.items():
   raw=re.sub(r'(<a href="#[^"]+">)'+re.escape(a)+r'(</a>)',lambda m:m.group(1)+b+m.group(2),raw)
  # Replace explanatory paragraphs, leaving individual publication section text intact.
  raw=re.sub(r'<p>These publications.*?</p>','<p>Selección de contribuciones metodológicas e interdisciplinares. El registro completo está disponible en <a href="https://orcid.org/0000-0003-3079-5855">ORCID</a> y <a href="https://scholar.google.com/citations?user=KUzOpI4AAAAJ">Google Scholar</a>.</p>',raw,flags=re.S)
  raw=re.sub(r'<p>Citation counts.*?</p>','<p><small>Citas consultadas en Google Scholar el 11 de septiembre de 2026. Se mantienen los asteriscos del servicio y no se suman registros duplicados o versiones.</small></p>',raw,flags=re.S)
  raw=re.sub(r'<p>Machine learning, Bayesian networks.*?</p>','<p>Aprendizaje automático, redes bayesianas e IA generativa para el análisis y el apoyo a decisiones. Algunos trabajos pertenecen también a las líneas de estadística espacial o eficiencia.</p>',raw,flags=re.S)
  raw=re.sub(r'<p>Research with.*?</p>','<p>Investigación con Juan Aparicio y colaboradores en fronteras de producción, aprendizaje automático y software abierto en R.</p>',raw,flags=re.S)
  raw=re.sub(r'<p class="lead">.*?</p>','<p class="lead">Inteligencia artificial, modelos bayesianos y espacio-temporales, eficiencia y productividad.</p>',raw,flags=re.S)
  raw=re.sub(r'<h2 id="academic-profile">.*', '<h2 id="academic-profile">Trayectoria académica</h2><p>Formación, docencia, liderazgo científico y participación en comités de ética.</p><p><a href="about.html">Consultar el perfil profesional</a> · <a href="https://portalinvestigacion.umh.es/investigadores/2181582/detalle">Registro académico completo en UMH</a></p>',raw,flags=re.S)
 else:
  raw=re.sub(r'<h2 id="academic-profile">.*','<h2 id="academic-profile">Academic profile</h2><p>Education, teaching, scientific leadership and research ethics.</p><p><a href="about.html">Read the professional profile</a> · <a href="https://portalinvestigacion.umh.es/investigadores/2181582/detalle">Full academic record at UMH</a></p>',raw,flags=re.S)
 s=pagehead(l,tr('Investigación y publicaciones','Research & publications',l),tr('Métodos para comprender, predecir y decidir.','Methods to understand, predict and decide.',l),tr('Una selección de investigación metodológica y colaboraciones interdisciplinares. Los títulos de los artículos se conservan en su idioma original.','Selected methodological research and interdisciplinary collaborations. Article titles are retained in their original language.',l))
 return s+f'<div class="wrap page-body split"><aside class="side-nav"><a href="#artificial-intelligence">{tr("Inteligencia artificial","Artificial intelligence",l)}</a><a href="#spatial-statistics">{tr("Modelos espaciales","Spatial models",l)}</a><a href="#efficiency-productivity">{tr("Eficiencia","Efficiency",l)}</a><a href="#highly-cited">{tr("Interdisciplinar","Interdisciplinary",l)}</a><a href="#academic-profile">{tr("Trayectoria","Profile",l)}</a></aside><div class="prose">'+raw+'</div></div>'

for l in ['es','en']:
 out=R if l=='es' else R/'en';out.mkdir(exist_ok=True)
 pages={'index':(tr('IA y ciencia de datos','AI & data science',l),home),'xbarber':(tr('Colaboración y transferencia','Collaboration & transfer',l),collaboration),'training':(tr('Formación especializada','Specialised training',l),training),'about':(tr('Perfil profesional','Professional profile',l),about),'cva':(tr('Investigación y publicaciones','Research & publications',l),research)}
 for k,(title,fn) in pages.items():
  desc=tr('Xavier Barber. Inteligencia artificial y ciencia de datos para empresas, administraciones y equipos de investigación. Universidad Miguel Hernández de Elche.','Xavier Barber. Artificial intelligence and data science for companies, public institutions and research teams. Universidad Miguel Hernández de Elche.',l)
  (out/(k+'.html')).write_text(shell(l,k,title,desc,fn(l)))
print('Built 10 bilingual pages')
